            "easy1_desc": "연구진은 시스템이 어떻게 움직이는지 모르는 상태에서 정확한 제어 정책을 세우기가 까다롭다는 점에 주목했는데요. 구체적인 동역학이나 잡음 분포를 모르는 이산 시간 확률 제어 시스템에서 검증과 정책 합성을 해내야 하는 과제였거든요. 쉽게 말하면, 정보가 부족한 상황에서도 시스템의 안전성을 믿을 수 있게 보장해야 한다는 말이에요.",
